INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c6040000-0000-4000-8000-000000000001', 'c6030000-0000-4000-8000-000000000001', 1, 'TEXT', 'Bài đọc IELTS thường có cấu trúc rõ: đoạn mở nêu vấn đề, các đoạn giữa đưa từng yếu tố hoặc lý do, đoạn cuối kết luận hoặc đưa giải pháp. Các từ "The first factor", "Another reason", "Finally" là bản đồ của bài. Khi làm Matching Headings, đọc câu đầu và câu cuối của đoạn, tìm ý chung chứ không chỉ một chi tiết, và loại các tiêu đề chỉ khớp một từ.');
