INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c6040000-0000-4000-8000-000000000004', 'c6030000-0000-4000-8000-000000000002', 1, 'TEXT', 'Đoạn tóm tắt viết lại bài đọc bằng từ khác, theo đúng thứ tự thông tin. Trước khi điền, đọc cả đoạn tóm tắt để nắm ý, rồi đoán từ loại cần điền: sau "the" là danh từ, sau "very" là tính từ. Tìm phần bài đọc tương ứng nhờ từ đồng nghĩa, chép đúng từ trong bài và kiểm tra ngữ pháp cả câu. Nếu đề cho danh sách từ, loại trước các từ sai từ loại.');
