INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c6040000-0000-4000-8000-000000000007', 'c6030000-0000-4000-8000-000000000003', 1, 'TEXT', 'Dạng điền form và ghi chú yêu cầu bạn viết đúng từ nghe được, thường không quá một hoặc hai từ. Đọc tiêu đề các dòng ghi chú để biết bài nói đi theo thứ tự nào. Chú ý thông tin bị loại: "the roof was repaired, but the biggest change is the climbing wall". Viết đúng chính tả và số; đáp án sai chính tả bị tính là sai.');
