INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c6040000-0000-4000-8000-000000000010', 'c6030000-0000-4000-8000-000000000004', 1, 'TEXT', 'Người nói dùng từ dẫn ý (signposting) để báo ý tiếp theo: "First", "Later", "In winter" (thời gian), "also" (thêm ý), "but", "on the other hand" (đối lập), "The main drawback is" (nhược điểm). Nghe được các từ này giúp bạn biết mình đang ở câu hỏi nào và không bị lạc. Khi nghe "but" hoặc "however", thông tin quan trọng thường nằm ngay sau đó.');
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('c6040000-0000-4000-8000-000000000010', (SELECT id FROM knowledge_points WHERE code = 'L60_SIGNPOSTING'));
