INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('c6070000-0000-4000-8000-000000000025', 'c6060000-0000-4000-8000-000000000025', 1, 'Which phrase signals a change of time in the talk?', '[{"optionKey": "A", "content": "In winter", "sortOrder": 1}, {"optionKey": "B", "content": "A single hive", "sortOrder": 2}, {"optionKey": "C", "content": "To tell other bees", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A"}', 1, 'In winter moves the talk to a new period.', 'EASY', 'PUBLISHED');
