INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c6040000-0000-4000-8000-000000000013', 'c6030000-0000-4000-8000-000000000005', 1, 'TEXT', 'Thì hiện tại hoàn thành nối quá khứ với hiện tại: "The population has doubled since 1990." Quá khứ hoàn thành chỉ việc xảy ra trước một mốc quá khứ: "By 2010, sales had reached 5 million." Tương lai hoàn thành dùng cho dự báo: "By 2030, the figure will have fallen." Từ mô tả xu hướng: rise, increase, climb (tăng); fall, drop, decline (giảm); remain stable, level off (ổn định); peak at (đạt đỉnh). Thêm mức độ: sharply, steadily, slightly.');
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('c6040000-0000-4000-8000-000000000013', (SELECT id FROM knowledge_points WHERE code = 'G60_PERFECT_TENSES'));
