INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c6040000-0000-4000-8000-000000000015', 'c6030000-0000-4000-8000-000000000006', 1, 'TEXT', 'Task 1 không yêu cầu mô tả mọi con số. Hãy chọn đặc điểm chính: xu hướng chung, số cao nhất và thấp nhất, sự thay đổi lớn nhất, và các so sánh nổi bật. Đoạn tổng quan (overview) nêu 2–3 đặc điểm này mà không cần số liệu cụ thể. Thân bài đưa số liệu để chứng minh, nhóm các mục giống nhau lại. Câu tổng quan thiếu là lỗi phổ biến làm mất điểm Task Achievement.');
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('c6040000-0000-4000-8000-000000000015', (SELECT id FROM knowledge_points WHERE code = 'W60_T1_KEY_FEATURES'));
