INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('c6070000-0000-4000-8000-000000000049', 'c6060000-0000-4000-8000-000000000049', 1, 'A line graph shows the percentage of households with internet access in two towns from 2000 to 2020. Town A rose from 20% to 90%; Town B rose from 10% to 60%. Which sentence is the best overview?', '[{"optionKey": "A", "content": "Overall, access rose in both towns, and Town A stayed ahead throughout.", "sortOrder": 1}, {"optionKey": "B", "content": "In 2000, Town A was at 20% and Town B was at 10%.", "sortOrder": 2}, {"optionKey": "C", "content": "Overall, access fell in Town B over the period.", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A", "distractors": {"B": "T1_NO_OVERVIEW", "C": "T1_DATA_MISREPORTED"}}', 1, 'An overview states the main trends; the second option only lists starting figures and the third misreads Town B.', 'MEDIUM', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('c6070000-0000-4000-8000-000000000049', (SELECT id FROM knowledge_points WHERE code = 'W60_T1_KEY_FEATURES'), 1.0);
INSERT INTO section_questions (id, section_id, question_version_id, sort_order, max_score) VALUES ('c60b0000-0000-4000-8000-000000000030', 'c60a0000-0000-4000-8000-000000000010', 'c6070000-0000-4000-8000-000000000049', 1, 1.0);
INSERT INTO questions (id, question_type, skill, purpose, status) VALUES ('c6060000-0000-4000-8000-000000000050', 'MULTIPLE_CHOICE', 'WRITING', 'LEARNING', 'PUBLISHED');
INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('c6070000-0000-4000-8000-000000000050', 'c6060000-0000-4000-8000-000000000050', 1, 'A line graph shows the percentage of households with internet access in two towns from 2000 to 2020. Town A rose from 20% to 90%; Town B rose from 10% to 60%. Which sentence reports Town B accurately?', '[{"optionKey": "A", "content": "Town B''s figure rose sixfold, from 10% to 60%.", "sortOrder": 1}, {"optionKey": "B", "content": "Town B''s figure doubled, from 10% to 60%.", "sortOrder": 2}, {"optionKey": "C", "content": "Town B was 10%, then later it was 60%, and Town A was 20% and then 90%.", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A", "distractors": {"B": "T1_DATA_MISREPORTED", "C": "T1_NO_OVERVIEW"}}', 1, 'From 10% to 60% is six times higher; ''doubled'' misreports it, and the last option lists numbers without a point.', 'MEDIUM', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('c6070000-0000-4000-8000-000000000050', (SELECT id FROM knowledge_points WHERE code = 'W60_T1_KEY_FEATURES'), 1.0);
INSERT INTO section_questions (id, section_id, question_version_id, sort_order, max_score) VALUES ('c60b0000-0000-4000-8000-000000000031', 'c60a0000-0000-4000-8000-000000000010', 'c6070000-0000-4000-8000-000000000050', 2, 1.0);
INSERT INTO questions (id, question_type, skill, purpose, status) VALUES ('c6060000-0000-4000-8000-000000000051', 'MULTIPLE_CHOICE', 'WRITING', 'LEARNING', 'PUBLISHED');
INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('c6070000-0000-4000-8000-000000000051', 'c6060000-0000-4000-8000-000000000051', 1, 'A line graph shows the percentage of households with internet access in two towns from 2000 to 2020. Town A rose from 20% to 90%; Town B rose from 10% to 60%. Which comparison of 2020 is correct?', '[{"optionKey": "A", "content": "Town A''s access was 30 percentage points higher than Town B''s.", "sortOrder": 1}, {"optionKey": "B", "content": "Both towns reached the same level.", "sortOrder": 2}, {"optionKey": "C", "content": "Town A: 90%. Town B: 60%.", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A", "distractors": {"B": "T1_DATA_MISREPORTED", "C": "T1_NO_OVERVIEW"}}', 1, '90% minus 60% is 30 points; the towns did not finish level, and bare figures make no comparison.', 'MEDIUM', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('c6070000-0000-4000-8000-000000000051', (SELECT id FROM knowledge_points WHERE code = 'W60_T1_KEY_FEATURES'), 1.0);
