INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('c6070000-0000-4000-8000-000000000052', 'c6060000-0000-4000-8000-000000000052', 1, 'A table shows the weekly hours teenagers spent on three activities in 2010 and 2020: social media 5 and 15, sport 6 and 4, reading 4 and 4. Which sentence is the best overview?', '[{"optionKey": "A", "content": "Overall, time on social media tripled, while sport fell and reading did not change.", "sortOrder": 1}, {"optionKey": "B", "content": "In 2010, teenagers spent five hours on social media and six on sport.", "sortOrder": 2}, {"optionKey": "C", "content": "Overall, all three activities increased.", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A", "distractors": {"B": "T1_NO_OVERVIEW", "C": "T1_DATA_MISREPORTED"}}', 1, 'The overview names each main trend; the second option is a detail and the third misreports sport and reading.', 'MEDIUM', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('c6070000-0000-4000-8000-000000000052', (SELECT id FROM knowledge_points WHERE code = 'W60_T1_KEY_FEATURES'), 1.0);
