INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('c6070000-0000-4000-8000-000000000053', 'c6060000-0000-4000-8000-000000000053', 1, 'A table shows the weekly hours teenagers spent on three activities in 2010 and 2020: social media 5 and 15, sport 6 and 4, reading 4 and 4. Which sentence about sport is accurate?', '[{"optionKey": "A", "content": "Time spent on sport fell from six hours to four.", "sortOrder": 1}, {"optionKey": "B", "content": "Time spent on sport rose from four hours to six.", "sortOrder": 2}, {"optionKey": "C", "content": "Sport was 6 hours and 4 hours, reading was 4 and 4, and social media was 5 and 15.", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A", "distractors": {"B": "T1_DATA_MISREPORTED", "C": "T1_NO_OVERVIEW"}}', 1, 'Sport went down; the second option reverses the years and the third dumps every figure without selecting.', 'MEDIUM', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('c6070000-0000-4000-8000-000000000053', (SELECT id FROM knowledge_points WHERE code = 'W60_T1_KEY_FEATURES'), 1.0);
