INSERT INTO lessons (id, topic_id, code, title, sort_order, status, estimated_minutes) VALUES ('c6030000-0000-4000-8000-000000000007', (SELECT id FROM topics WHERE code = 'IELTS_6_0_WRITING'), 'W60-3', 'Liên kết trong đoạn văn', 3, 'PUBLISHED', 10);
INSERT INTO lesson_knowledge_points (lesson_id, knowledge_point_id) VALUES ('c6030000-0000-4000-8000-000000000007', (SELECT id FROM knowledge_points WHERE code = 'W60_PARAGRAPH_COHESION'));
INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c6040000-0000-4000-8000-000000000017', 'c6030000-0000-4000-8000-000000000007', 1, 'TEXT', 'Một đoạn văn mạch lạc khi các câu nối với nhau rõ ràng. Dùng từ thay thế để tránh lặp: "Many students work part-time. This helps them..." ("This" chỉ việc đi làm thêm). Dùng đại từ (they, it), từ đồng nghĩa và từ nối vừa đủ, không nhồi "Moreover, Furthermore" vào mọi câu. Mỗi câu nên bắt đầu bằng thông tin đã biết và kết thúc bằng thông tin mới.');
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('c6040000-0000-4000-8000-000000000017', (SELECT id FROM knowledge_points WHERE code = 'W60_PARAGRAPH_COHESION'));
INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type) VALUES ('c6040000-0000-4000-8000-000000000018', 'c6030000-0000-4000-8000-000000000007', 2, 'EXERCISE');
