INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('c6070000-0000-4000-8000-000000000055', 'c6060000-0000-4000-8000-000000000055', 1, 'What does ''This'' refer to? ''Many cities have banned cars from their centres. This has reduced pollution.''', '[{"optionKey": "A", "content": "Banning cars from city centres", "sortOrder": 1}, {"optionKey": "B", "content": "Pollution", "sortOrder": 2}, {"optionKey": "C", "content": "Many cities", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A"}', 1, 'This refers back to the whole action in the first sentence.', 'MEDIUM', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('c6070000-0000-4000-8000-000000000055', (SELECT id FROM knowledge_points WHERE code = 'W60_PARAGRAPH_COHESION'), 1.0);
